private let keepGenerators = [
    "IntegerGenerator", "StringGenerator", "TernaryOperationGenerator",
    "PlainFunctionGenerator", "AsyncFunctionGenerator", "AwaitGenerator",
    "SubroutineReturnGenerator", "TryCatchGenerator",
]

private let mojoDisabledGenerators: [String] = CodeGenerators.map { $0.name }
    .filter {
        !keepGenerators.contains($0)
    }

let mojoAuthenticatorProfile = Profile(
    processArgs: { _ in return [] },
    processArgsReference: nil,
    processEnv: [
        "ASAN_OPTIONS": "detect_odr_violation=0:abort_on_error=1", "DISPLAY": ":20",
    ],
    maxExecsBeforeRespawn: 50,
    timeout: Timeout.interval(11000, 11000),
    codePrefix: """
        let globalRemote = null;
        function getOrCreatePrimaryRemote() {
            if (!globalRemote) {
                globalRemote = blink.mojom.Authenticator.getRemote();
            }
            return globalRemote;
        }
        """,
    codeSuffix: "if (globalRemote) {globalRemote.$.close()}",
    ecmaVersion: v8Profile.ecmaVersion,
    startupTests: [
        ("fuzzilli('FUZZILLI_PRINT', 'test')", .shouldSucceed),
        (
            """
            if (typeof blink == 'undefined' \
            || blink?.mojom?.Authenticator === undefined) \
            throw 'Authenticator not found'
            """,
            .shouldSucceed
        ),
    ] + v8Profile.startupTests,
    additionalCodeGenerators: [
        (MojoMethodCallGenerator, 10000),
        (MojoPropertyRetrievalGenerator, 10000),
        (MojoUint8MojoArrayGenerator, 1),
        (MojoBlinkMojomPublicKeyCredentialParametersMojoArrayGenerator, 1),
        (MojoBlinkMojomPublicKeyCredentialDescriptorMojoArrayGenerator, 1),
        (MojoBlinkMojomAuthenticatorTransportMojoArrayGenerator, 1),
        (MojoBlinkMojomHintMojoArrayGenerator, 1),
        (MojoStringMojoArrayGenerator, 1),
        (MojoBlinkMojomPRFValuesMojoArrayGenerator, 1),
        (MojoUint8MojoArrayMojoArrayGenerator, 1),
        (MojoBlinkMojomWebAuthnClientCapabilityMojoArrayGenerator, 1),
    ] + commonMojoCodeGenerators,
    additionalProgramTemplates: WeightedList([]),
    disabledCodeGenerators: mojoDisabledGenerators,
    disabledMutators: [
        "ExplorationMutator", "ProbingMutator", "PropertyAccessorMutator"
    ],
    additionalBuiltins: mojoBuiltins.merging(commonMojoBuiltins) { (existing, _) in existing },
    additionalObjectGroups: mojoObjectGroups,
    additionalEnumerations: [
        .jsBlinkMojomPublicKeyCredentialType,
        .jsBlinkMojomAuthenticatorTransport,
        .jsBlinkMojomAuthenticatorAttachment,
        .jsBlinkMojomResidentKeyRequirement,
        .jsBlinkMojomUserVerificationRequirement,
        .jsBlinkMojomHint,
        .jsBlinkMojomAttestationConveyancePreference,
        .jsBlinkMojomProtectionPolicy,
        .jsBlinkMojomLargeBlobSupport,
        .jsBlinkMojomAuthenticatorStatus,
        .jsBlinkMojomMediation,
        .jsBlinkMojomCredentialType,
    ] + commonMojoEnumerations,
    additionalOptionsBags: [] + commonMojoOptionsBags,
    optionalPostProcessor: nil
)
